-- Ontology knowledge: products, class hierarchy, and entity / asset / part-of views.
-- Generated by `python -m oag_semantic.platform_knowledge` from the ontology (knowledge/ontology/*.ttl and
-- knowledge/vocabulary.yaml, ADR 0047). Do not edit: change the ontology and regenerate.

-- Products and their grouping (skos:broader); product_metric = the governed metrics that measure
-- each product: its own, else those of the products under it ("total liquids" -> oil + water).
DROP TABLE IF EXISTS knowledge.product;
GO
CREATE TABLE knowledge.product (product_key VARCHAR(400), metric VARCHAR(400), broader VARCHAR(400), definition VARCHAR(400));
GO
