-- The class hierarchy (rdfs:subClassOf, transitive): (class, superclass).
DROP TABLE IF EXISTS knowledge.ontology_class;
GO
CREATE TABLE knowledge.ontology_class (class_name VARCHAR(400), superclass_name VARCHAR(400));
GO
INSERT INTO knowledge.ontology_class VALUES
  ('Facility', 'Asset'),
  ('Field', 'Asset'),
  ('Well', 'Asset');
GO
-- Every mapped instance and its class, with the ontology's IRIs (from the R2RML mapping).
CREATE OR ALTER VIEW knowledge.entity AS
SELECT CONCAT('https://example.org/oag/id/facility/', CAST(t.FACILITY_ID AS VARCHAR(400)), '/', REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CAST(t.FACILITY_TYPE AS VARCHAR(400)), '%', '%25'), ' ', '%20'), '!', '%21'), '"', '%22'), '#', '%23'), '$', '%24'), '&', '%26'), '''', '%27'), '(', '%28'), ')', '%29'), '*', '%2A'), '+', '%2B'), ',', '%2C'), '/', '%2F'), ':', '%3A'), ';', '%3B'), '<', '%3C'), '=', '%3D'), '>', '%3E'), '?', '%3F'), '@', '%40'), '[', '%5B'), ']', '%5D'), '^', '%5E'), '`', '%60'), '{', '%7B'), '|', '%7C'), '}', '%7D')) AS iri, 'Facility' AS class_name FROM canonical.facility t
UNION ALL
SELECT CONCAT('https://example.org/oag/id/field/', CAST(t.FIELD_ID AS VARCHAR(400))) AS iri, 'Field' AS class_name FROM canonical.field t
UNION ALL
SELECT CONCAT('https://example.org/oag/id/well/', CAST(t.WELL_ID AS VARCHAR(400))) AS iri, 'Well' AS class_name FROM canonical.well t;
GO
-- Inheritance: an asset is an entity whose class is a subclass of Asset.
CREATE OR ALTER VIEW knowledge.asset AS
SELECT e.iri, e.class_name FROM knowledge.entity e
JOIN knowledge.ontology_class c ON c.class_name = e.class_name AND c.superclass_name = 'Asset';
GO
-- Direct part-of links: the subproperties of oag:partOf, as the mapping defines them.
CREATE OR ALTER VIEW knowledge.part_of_edge AS
SELECT CONCAT('https://example.org/oag/id/well/', CAST(t.WELL_ID AS VARCHAR(400))) AS part, CONCAT('https://example.org/oag/id/facility/', CAST(p.FACILITY_ID AS VARCHAR(400)), '/', REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CAST(p.FACILITY_TYPE AS VARCHAR(400)), '%', '%25'), ' ', '%20'), '!', '%21'), '"', '%22'), '#', '%23'), '$', '%24'), '&', '%26'), '''', '%27'), '(', '%28'), ')', '%29'), '*', '%2A'), '+', '%2B'), ',', '%2C'), '/', '%2F'), ':', '%3A'), ';', '%3B'), '<', '%3C'), '=', '%3D'), '>', '%3E'), '?', '%3F'), '@', '%40'), '[', '%5B'), ']', '%5D'), '^', '%5E'), '`', '%60'), '{', '%7B'), '|', '%7C'), '}', '%7D')) AS whole, 'atFacility' AS property FROM canonical.well t JOIN canonical.facility p ON t.FACILITY_ID = p.FACILITY_ID
UNION ALL
SELECT CONCAT('https://example.org/oag/id/facility/', CAST(t.FACILITY_ID AS VARCHAR(400)), '/', REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(CAST(t.FACILITY_TYPE AS VARCHAR(400)), '%', '%25'), ' ', '%20'), '!', '%21'), '"', '%22'), '#', '%23'), '$', '%24'), '&', '%26'), '''', '%27'), '(', '%28'), ')', '%29'), '*', '%2A'), '+', '%2B'), ',', '%2C'), '/', '%2F'), ':', '%3A'), ';', '%3B'), '<', '%3C'), '=', '%3D'), '>', '%3E'), '?', '%3F'), '@', '%40'), '[', '%5B'), ']', '%5D'), '^', '%5E'), '`', '%60'), '{', '%7B'), '|', '%7C'), '}', '%7D')) AS part, CONCAT('https://example.org/oag/id/field/', CAST(t.FIELD_ID AS VARCHAR(400))) AS whole, 'inField' AS property FROM canonical.facility t
UNION ALL
SELECT CONCAT('https://example.org/oag/id/well/', CAST(t.WELL_ID AS VARCHAR(400))) AS part, CONCAT('https://example.org/oag/id/field/', CAST(t.FIELD_ID AS VARCHAR(400))) AS whole, 'inField' AS property FROM canonical.well t;
GO
-- oag:partOf is transitive: the closure, as joins up to the longest chain the mapping allows.
CREATE OR ALTER VIEW knowledge.part_of AS
SELECT DISTINCT part, whole FROM (
SELECT e1.part, e1.whole FROM knowledge.part_of_edge e1
UNION ALL
SELECT e1.part, e2.whole FROM knowledge.part_of_edge e1 JOIN knowledge.part_of_edge e2 ON e1.whole = e2.part
) chains;
GO
